CREATE OR REPLACE FUNCTION public.post_href(p_post_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
           when c.slug is null then '/posts/' || p.id
           else '/cars/' || c.slug || '/activity/' || p.id
         end
  from public.activity_posts p
  left join public.cars c on c.id = p.car_id
  where p.id = p_post_id;
$function$;

comment on function public.post_href(p_post_id uuid) is 'Where a post lives — /cars/{slug}/activity/{id}, or /posts/{id} with no car. Twin of postHref() in src/lib/activity/href.ts.';

grant execute on function public.post_href(p_post_id uuid) to service_role;
